import { NextResponse } from "next/server"

const GOOGLE_MAPS_API_KEY = process.env.GOOGLE_MAPS_API_KEY

export async function GET(request: Request) {
  const { searchParams } = new URL(request.url)
  const lat = Number(searchParams.get("lat"))
  const lng = Number(searchParams.get("lng"))

  if (![lat, lng].every((v) => Number.isFinite(v))) {
    return NextResponse.json({ error: "Invalid coordinates" }, { status: 400 })
  }
  if (Math.abs(lat) > 90 || Math.abs(lng) > 180) {
    return NextResponse.json({ error: "Coordinates out of range" }, { status: 400 })
  }

  if (!GOOGLE_MAPS_API_KEY || GOOGLE_MAPS_API_KEY === "demo") {
    // Return demo data for development
    return NextResponse.json({
      address: `Demo Location near ${lat?.toFixed(4)}, ${lng?.toFixed(4)} - Liberia`
    })
  }

  const params = new URLSearchParams({
    latlng: `${lat},${lng}`,
    key: GOOGLE_MAPS_API_KEY,
  })

  const res = await fetch(`https://maps.googleapis.com/maps/api/geocode/json?${params.toString()}`, {
    cache: "no-store",
  })

  if (!res.ok) {
    return NextResponse.json({ error: "Geocoding failed" }, { status: 502 })
  }

  const data = await res.json()
  const address = data?.results?.[0]?.formatted_address
  if (!address) {
    return NextResponse.json({ error: "No address found" }, { status: 404 })
  }

  return NextResponse.json({ address })
}
